assert L['en'].keys() == L['fr'].keys() == L['es'].keys(), set(L['en']) ^ set(L['fr']) ^ set(L['es'])
for lang, d in L.items():
    p = os.path.join(LOC, lang, 'ui.js')
    s = open(p, encoding='utf-8').read()
    if '\n  tiktok: {' in s:
        print(lang, 'already has tiktok texts — skipped'); continue
    i = s.rstrip().rfind('});')
    body = ''.join('    %s: %s,\n' % (k, json.dumps(v, ensure_ascii=False)) for k, v in d.items())
    block = '  // v20261112b: Continue with TikTok, sign-in methods, add-your-email card, Share to TikTok\n  tiktok: {\n' + body + '  },\n'
    head = s[:i].rstrip()
    if not head.endswith(','): head += ','
    open(p, 'w', encoding='utf-8').write(head + '\n' + block + '});\n')
    print(lang, 'ok —', len(d), 'keys added')
